import base64,pathlib,subprocess,sys
p=pathlib.Path('/content/q35moe-calibrated-controller.py')
p.write_bytes(base64.b64decode(''))
log=open('/content/q35moe-calibrated-controller.log','w')
child=subprocess.Popen([sys.executable,'-u',str(p)],stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
print({'pid':child.pid,'log':log.name})
